function columnLetters(n) {
  if (!Number.isInteger(n) || n < 1 || n > 16384) throw new Error("Invalid column");
  let out = "";
  for (; n > 0; n = Math.floor((n - 1) / 26)) out = String.fromCharCode(65 + ((n - 1) % 26)) + out;
  return out;
}
function addressParts(address) {
  const m = /^([A-Z]+)([1-9][0-9]*)$/i.exec(address);
  if (!m) throw new Error("Invalid address: " + address);
  let col = 0;
  for (const ch of m[1].toUpperCase()) col = col * 26 + ch.charCodeAt(0) - 64;
  return { row: Number(m[2]), col };
}
function getSourceFormula(doc, sheetName, address) {
  const cell = doc.sheets[sheetName]?.cells[address];
  if (!cell) throw new Error("Cell not found: " + sheetName + "!" + address);
  if (!cell.formula_ref) return null;
  const t = doc.formula_templates[cell.formula_ref];
  if (!t) throw new Error("Unknown formula template");
  const a = addressParts(t.anchor), b = addressParts(address);
  const dr = b.row - a.row, dc = b.col - a.col;
  const part = p => {
    const row = p.row + (p.abs_row ? 0 : dr);
    if (row < 1 || row > 1048576) throw new Error("Invalid row");
    return (p.abs_col ? "$" : "") + columnLetters(p.col + (p.abs_col ? 0 : dc)) + (p.abs_row ? "$" : "") + row;
  };
  return t.translation_tokens.map(x => typeof x === "string" ? x : x.sheet_prefix + part(x.start) + (x.end ? ":" + part(x.end) : "")).join("");
}
// This reconstructs the source text only. It DOES NOT evaluate Excel formulas.
// Example: getSourceFormula(source, "Voltas", "AI45");
